      const ticks = Array.from({ length: 8 }, (_, i) => { const t = i * Math.PI / 4; return line(50 + 33 * Math.cos(t), 50 + 33 * Math.sin(t), 50 + 37 * Math.cos(t), 50 + 37 * Math.sin(t), 1.5, '#b5b5bf'); }).join('');
