  // ------------------------------------------------------------ family: overlay (set operations on lines/dots)
  const OPS = { or: (a, b) => a | b, xor: (a, b) => a ^ b, and: (a, b) => a & b, sub: (a, b) => a & ~b, bsub: (a, b) => b & ~a, first: a => a, second: (a, b) => b };
