    if (alt.length < 2) return null;
    const pr = R.sample(alt, 2).map(o => ({ apply: at => ({ ...at, s: o.v }), why: altWhy(o.k) }));
    const e = R.int(0, n - 1);
    const tog = s => (s ^ (1 << e)) || (s | (1 << ((e + 1) % n)));
